import {
  AccountsApi, ResponseError, VendorOnboardingApi, VendorTaxDataFromJSON,
  type AccountProfile, type ChangeVendorTeamMember, type ChangeVendorTeamMemberRoleEnum,
  type ChangeVendorTeamMemberStatusEnum, type InviteVendorTeamRoleEnum, type SaveVendorStore,
  type VendorBusinessContact, type VendorBusinessDraft, type VendorBusinessDraftBusinessTypeEnum,
  type VendorBusinessDraftClassificationEnum, type VendorBusinessDraftNichesEnum,
  type VendorCommissionTerms, type VendorDocument, type VendorReadiness, type VendorReviewDecisionEnum,
  type VendorSetup, type VendorStoreMedia, type VendorTaxProfile, type VendorTeamInvitation,
  type VendorTeamMember, type VendorVehicle, type VendorVerificationRow,
} from '@materyalph/api-client-ts'
import { useCallback, useEffect, useMemo, useState, type ReactNode } from 'react'
import { Button } from './button'
import { Field } from './field'
import { StatusMessage } from './status-message'
import { createWebApiConfiguration } from './web-api-session'

type Props = { portal: 'vendors' | 'admin'; basePath: string; accountPath: string; dashboardPath?: string }
type VendorSection = 'Overview' | 'Business identity' | 'Contacts and location' | 'Evidence' | 'Tax profile' | 'Verification review' | 'Store profile' | 'Fulfillment' | 'Payment and commission' | 'Team accounts' | 'Activation'
type AdminSection = 'Queue' | 'Store Verification' | 'Store Setup' | 'Activation'
type Section = VendorSection | AdminSection

const vendorSections: VendorSection[] = ['Overview', 'Business identity', 'Contacts and location', 'Evidence', 'Tax profile', 'Verification review', 'Store profile', 'Fulfillment', 'Payment and commission', 'Team accounts', 'Activation']
const adminSections: AdminSection[] = ['Queue', 'Store Verification', 'Store Setup', 'Activation']
const businessTypes = ['SOLE_PROPRIETORSHIP', 'PARTNERSHIP', 'CORPORATION', 'ONE_PERSON_CORPORATION', 'COOPERATIVE'] as const
const niches = ['CONSTRUCTION_MATERIALS', 'ELECTRICAL_SUPPLIES', 'PLUMBING_SANITARY', 'TOOLS_EQUIPMENT', 'FINISHING_MATERIALS', 'FASTENERS_HARDWARE', 'CEMENT_CONCRETE', 'ROOFING_MATERIALS', 'FORMWORKS_SCAFFOLDING', 'WOOD_LUMBER', 'LANDSCAPING_EXTERIOR', 'STEEL_REINFORCEMENT', 'TOOLS_ACCESSORIES', 'MASONRY', 'INSULATION_WATERPROOFING', 'AGGREGATES', 'DRAINAGE_SEPTIC', 'CONSTRUCTION_CHEMICALS', 'FLOORING_MATERIALS', 'WALL_CEILING', 'HVAC_MATERIALS', 'SANITARY_FIXTURES', 'FIRE_PROTECTION', 'PAINTS_FINISHES', 'ADHESIVES_SEALANTS', 'DOORS_WINDOWS_GLASS', 'OTHER'] as const
const documentTypes = ['GOVERNMENT_ID', 'DTI', 'SEC', 'CDA', 'LGU_PERMIT', 'BIR_COR', 'REGULATORY', 'ISO_CERTIFICATION', 'TAX_DECLARATION', 'WITHHOLDING_DECLARATION'] as const
const inputClass = 'min-h-12 w-full rounded-control border border-border-default bg-surface-primary px-3 text-text-strong focus:outline-2 focus:outline-focus-ring'
const label = (value: string) => value.replaceAll('_', ' ').replace(/([a-z])([A-Z])/g, '$1 $2').toLowerCase().replace(/^./, c => c.toUpperCase())
const stamp = (value?: string | null) => value ? `${new Date(value).toLocaleString('en-PH', { timeZone: 'Asia/Manila' })} (Asia/Manila)` : 'Not recorded'
const emptyContact = (): VendorBusinessContact => ({ fullName: '', position: '', email: '', telephoneE164: '', authorizedRepresentative: false, isPrimary: true, verificationCommunication: true, accountAdministrationCommunication: true, generalAdministrationCommunication: true })
const emptyVehicle = (): VendorVehicle => ({ vehicleType: 'TRUCK', name: '', numberAvailable: 1, capacityKg: 1, cargoLengthM: 1, cargoWidthM: 1, cargoHeightM: 1, heavyVehicleClassification: 'LIGHT_DUTY', baseFeeCentavos: 0, perKmCentavos: 0, maximumDistanceKm: 1 })

function Select({ title, children, ...props }: { title: string; children: ReactNode } & React.SelectHTMLAttributes<HTMLSelectElement>) { return <label className="grid gap-2 text-sm font-semibold">{title}<select className={inputClass} {...props}>{children}</select></label> }
function Check({ title, ...props }: { title: string } & React.InputHTMLAttributes<HTMLInputElement>) { return <label className="flex min-h-12 items-center gap-3 text-sm"><input className="h-5 w-5" type="checkbox" {...props} />{title}</label> }
function Pill({ value }: { value: string }) { return <span className="inline-flex rounded-full border border-border-default bg-surface-secondary px-3 py-1 text-xs font-semibold">{label(value)}</span> }
function FinishLater({ href = '/dashboard' }: { href?: string }) { return <a className="inline-flex min-h-12 rounded-control border border-border-default px-5 py-3 font-semibold" href={href}>Finish Later</a> }

export function VendorOnboardingWorkspace({ portal, basePath, accountPath, dashboardPath = '/dashboard' }: Props) {
  const admin = portal === 'admin'
  const [account, setAccount] = useState<AccountProfile | null>(null)
  const [organization, setOrganization] = useState('')
  const [section, setSection] = useState<Section>(admin ? 'Queue' : 'Overview')
  const [readiness, setReadiness] = useState<VendorReadiness | null>(null)
  const [business, setBusiness] = useState<VendorBusinessDraft>({ contacts: [emptyContact()] })
  const [businessReason, setBusinessReason] = useState<string | null>(null)
  const [emailVerifiedAt, setEmailVerifiedAt] = useState<string | null>(null)
  const [documents, setDocuments] = useState<VendorDocument[]>([])
  const [tax, setTax] = useState<VendorTaxProfile | null>(null)
  const [setup, setSetup] = useState<VendorSetup | null>(null)
  const [media, setMedia] = useState<VendorStoreMedia[]>([])
  const [terms, setTerms] = useState<VendorCommissionTerms | null>(null)
  const [team, setTeam] = useState<VendorTeamMember[]>([])
  const [invitations, setInvitations] = useState<VendorTeamInvitation[]>([])
  const [queue, setQueue] = useState<VendorVerificationRow[]>([])
  const [page, setPage] = useState(1)
  const [lastPage, setLastPage] = useState(1)
  const [busy, setBusy] = useState(false)
  const [message, setMessage] = useState<{ tone: 'error' | 'success' | 'info'; text: string } | null>(null)
  const [invitationKey, setInvitationKey] = useState(() => crypto.randomUUID())
  const client = useMemo(() => new VendorOnboardingApi(createWebApiConfiguration(basePath, { refreshSession: true })), [basePath])

  const reportError = useCallback(async (failure: unknown) => {
    let text = 'The request could not finish. Check your connection and retry.'
    if (failure instanceof ResponseError) {
      const body: unknown = await failure.response.clone().json().catch(() => null)
      if (failure.response.status === 401) text = 'Your session expired. Sign in again.'
      if (failure.response.status === 429) text = 'The service is temporarily rate limited. Wait a moment, then retry.'
      if (typeof body === 'object' && body !== null && 'errors' in body && Array.isArray(body.errors)) {
        const first = body.errors[0]
        if (typeof first === 'object' && first !== null && 'message' in first && typeof first.message === 'string') text = first.message
      }
    }
    setMessage({ tone: 'error', text })
  }, [])

  const load = useCallback(async () => {
    setBusy(true)
    try {
      const profile = (await new AccountsApi(createWebApiConfiguration(basePath, { refreshSession: true })).getAccountProfile({ accountPortal: portal })).data
      setAccount(profile)
      if (!admin && profile.role !== 'OWNER' && profile.permissions.includes('staff.manage') && section !== 'Team accounts') {
        setSection('Team accounts')
        return
      }
      const id = admin ? organization : profile.organizationId ?? ''
      if (!admin) setOrganization(id)
      if (admin && (!id || section === 'Queue')) {
        const result = await client.listVendorVerificationQueue({ page, perPage: 20 })
        setQueue(result.data); setLastPage(Number(result.meta.last_page ?? 1)); return
      }
      if (!id) return
      setReadiness((await (admin ? client.getAdminVendorReadiness({ organization: id }) : client.getVendorReadiness({ organization: id }))).data)
      if (admin || ['Business identity', 'Contacts and location', 'Verification review'].includes(section)) {
        const result = (await (admin ? client.getAdminVendorBusiness({ organization: id }) : client.getVendorBusiness({ organization: id }))).data
        setBusiness({ contacts: [emptyContact()], ...result.draft }); setBusinessReason(result.reviewReason ?? null); setEmailVerifiedAt(result.storeEmailVerification.verifiedAt ?? null)
      }
      if (admin || ['Evidence', 'Tax profile', 'Verification review'].includes(section)) {
        const result = await (admin ? client.listAdminVendorDocuments({ organization: id, page, perPage: 50 }) : client.listVendorDocuments({ organization: id, page, perPage: 50 }))
        setDocuments(result.data)
      }
      if (admin || ['Tax profile', 'Verification review'].includes(section)) setTax((await (admin ? client.getAdminVendorTaxProfile({ organization: id }) : client.getVendorTaxProfile({ organization: id }))).data)
      if (!admin && ['Store profile', 'Fulfillment', 'Payment and commission'].includes(section)) setSetup((await client.getVendorSetup({ organization: id })).data)
      if (admin || section === 'Store profile') setMedia((await (admin ? client.listAdminVendorStoreMedia({ organization: id }) : client.listVendorStoreMedia({ organization: id }))).data)
      if (!admin && section === 'Payment and commission') { setTerms((await client.getVendorCommissionTerms({ organization: id })).data); setTax((await client.getVendorTaxProfile({ organization: id })).data) }
      if (!admin && section === 'Team accounts') { const result = await client.getVendorTeam({ organization: id, page, perPage: 20 }); setTeam(result.data.members); setInvitations((await client.listVendorTeamInvitations({ organization: id, page, perPage: 20 })).data) }
    } catch (failure) { await reportError(failure) } finally { setBusy(false) }
  }, [admin, basePath, client, organization, page, portal, reportError, section])
  useEffect(() => { void load() }, [load])

  async function act(action: () => Promise<unknown>, success: string) { setBusy(true); setMessage(null); try { await action(); setMessage({ tone: 'success', text: success }); await load() } catch (failure) { await reportError(failure) } finally { setBusy(false) } }
  async function previewMedia(id: string) {
    setBusy(true); setMessage(null)
    try {
      const blob = await client.previewVendorStoreMedia({ organization, media: id })
      const url = URL.createObjectURL(blob)
      const link = document.createElement('a')
      link.href = url; link.target = '_blank'; link.rel = 'noopener noreferrer'; link.click()
      window.setTimeout(() => URL.revokeObjectURL(url), 60_000)
    } catch (failure) { await reportError(failure) } finally { setBusy(false) }
  }
  const lockVersion = readiness?.lockVersion ?? setup?.lockVersion ?? tax?.lockVersion ?? 1
  const owner = account?.role === 'OWNER'
  const availableSections: Section[] = admin ? adminSections : owner ? vendorSections : account?.permissions.includes('staff.manage') ? ['Team accounts'] : []
  const choose = (next: Section) => { setSection(next); setPage(1); setMessage(null) }

  return <main className="min-h-screen bg-surface-canvas text-text-strong">
    <header className="border-b border-border-default bg-surface-primary px-5 py-6"><div className="mx-auto flex max-w-7xl flex-wrap items-center justify-between gap-4"><div><p className="text-sm font-semibold text-action-primary">MateryalPH · {admin ? 'Admin review' : 'Vendor onboarding'}</p><h1 className="mt-1 text-3xl font-bold">{admin ? 'Vendor onboarding control center' : 'Set up your store'}</h1></div><div className="flex gap-4"><a className="py-3 font-semibold text-action-primary" href={dashboardPath}>{admin ? 'Admin workspace' : 'Dashboard'}</a><a className="py-3 font-semibold text-action-primary" href={accountPath}>Account &amp; security</a></div></div></header>
    <div className="mx-auto grid max-w-7xl gap-6 px-5 py-6 lg:grid-cols-[260px_minmax(0,1fr)]"><nav aria-label="Onboarding steps" className="flex content-start gap-2 overflow-x-auto pb-2 lg:flex-col">{availableSections.map(item => <button key={item} type="button" onClick={() => choose(item)} aria-current={section === item ? 'step' : undefined} className={`min-h-11 shrink-0 rounded-control border px-4 text-left text-sm font-semibold ${section === item ? 'border-action-primary bg-action-primary text-white' : 'border-border-default bg-surface-primary'}`}>{item}</button>)}</nav>
      <section className="min-w-0 space-y-6" aria-busy={busy}>{message && <StatusMessage tone={message.tone}>{message.text}</StatusMessage>}{busy && <p role="status">Loading or saving…</p>}
        {!admin && account && !owner && !account.permissions.includes('staff.manage') && <StatusMessage tone="info">Staff accounts do not repeat Vendor Onboarding and cannot bypass Store Activation. Ask the Vendor Owner to complete or correct onboarding.</StatusMessage>}
        {admin && section === 'Queue' && <Queue rows={queue} busy={busy} page={page} lastPage={lastPage} setPage={setPage} onOpen={id => { setOrganization(id); choose('Store Verification') }} />}
        {admin && organization && section === 'Store Verification' && <AdminVerification readiness={readiness} business={business} documents={documents} tax={tax} busy={busy} lockVersion={lockVersion} onBusiness={(decision, reason, regulatory, basis) => void act(() => client.reviewVendorBusiness({ organization, vendorBusinessReview: { lockVersion, decision, reason, regulatoryEvidenceRequired: regulatory, regulatoryReviewBasis: basis } }), 'Business review recorded and audit logged.')} onDocument={(document, review) => void act(() => client.reviewVendorDocument({ organization, version: document.id, vendorDocumentReview: review }), 'Document review recorded and audit logged.')} onTax={(version, decision, reason) => void act(() => client.reviewVendorTaxProfile({ organization, version, vendorReview: { lockVersion, decision, reason } }), 'Tax Profile review recorded independently.')} />}
        {admin && organization && section === 'Store Setup' && <AdminSetup readiness={readiness} media={media} busy={busy} onReview={(id, decision, reason) => void act(() => client.reviewVendorStoreMedia({ organization, media: id, vendorReview: { lockVersion, decision, reason } }), 'Store media review recorded.')} />}
        {admin && organization && section === 'Activation' && <ReadinessPanel readiness={readiness} />}
        {!admin && owner && section === 'Overview' && <Overview readiness={readiness} />}
        {!admin && owner && section === 'Business identity' && <BusinessIdentity business={business} setBusiness={setBusiness} emailVerifiedAt={emailVerifiedAt} busy={busy} onSave={() => void act(() => client.saveVendorBusiness({ organization, saveVendorBusiness: { lockVersion, submit: false, business } }), 'Business identity draft saved.')} onRequest={() => void act(() => client.requestVendorStoreEmailVerification({ organization, vendorStoreEmailVerificationRequest: { lockVersion, email: business.storeEmail ?? '' } }), 'Verification code sent to the Store Email.')} onConfirm={code => void act(() => client.confirmVendorStoreEmailVerification({ organization, vendorStoreEmailVerificationConfirmation: { lockVersion, email: business.storeEmail ?? '', code } }), 'Store Email verified.')} />}
        {!admin && owner && section === 'Contacts and location' && <ContactsLocation business={business} setBusiness={setBusiness} busy={busy} onSave={() => void act(() => client.saveVendorBusiness({ organization, saveVendorBusiness: { lockVersion, submit: false, business } }), 'Contacts and registered location saved.')} />}
        {!admin && owner && section === 'Evidence' && <Evidence documents={documents} busy={busy} onUpload={(type, file) => void act(() => client.uploadVendorDocument({ organization, lockVersion, documentType: type, file }), 'Private evidence uploaded for file-safety checks and Admin review.')} />}
        {!admin && owner && section === 'Tax profile' && <TaxProfile tax={tax} documents={documents} owner={owner} busy={busy} onSave={(profile, attest) => void act(() => client.saveVendorTaxProfile({ organization, saveVendorTax: { lockVersion, attest, profile: VendorTaxDataFromJSON(profile) } }), attest ? 'Vendor Tax Profile attested and submitted.' : 'Vendor Tax Profile correction draft saved.')} />}
        {!admin && owner && section === 'Verification review' && <VerificationReview readiness={readiness} business={business} documents={documents} tax={tax} reason={businessReason} busy={busy} dashboardPath={dashboardPath} onSubmit={() => void act(() => client.saveVendorBusiness({ organization, saveVendorBusiness: { lockVersion, submit: true, business } }), 'Store Verification is PENDING_VERIFICATION. You may proceed to Store Setup.')} onProceed={() => choose('Store profile')} />}
        {!admin && owner && section === 'Store profile' && <StoreProfile setup={setup} media={media} storeName={readiness?.storeName ?? business.storeName ?? ''} busy={busy} onUpload={(kind, alt, file) => void act(() => client.uploadVendorStoreMedia({ organization, lockVersion, kind, altText: alt, file }), 'Store media uploaded.')} onPreview={id => void previewMedia(id)} onRemove={id => void act(() => client.removeVendorStoreMedia({ organization, media: id, vendorVersionMutation: { lockVersion } }), 'Store media removed.')} />}
        {!admin && owner && section === 'Fulfillment' && <Fulfillment setup={setup} busy={busy} onSave={data => void act(() => client.saveVendorStore({ organization, saveVendorStore: { lockVersion, ...data } }), 'Store Setup progress saved.')} />}
        {!admin && owner && section === 'Payment and commission' && <PaymentCommission setup={setup} tax={tax} terms={terms} busy={busy} onConnect={() => void act(() => client.connectVendorTest({ organization, connectVendorTest: { lockVersion, withholdingDemoScenario: 'DEMO_PLATFORM_WITHHOLDER' } }), 'Xendit TEST onboarding state recorded.')} onReconcile={() => void act(() => client.reconcileVendorTestConnection({ organization, vendorVersionMutation: { lockVersion } }), 'Xendit TEST connection reconciled.')} onAccept={id => void act(() => client.acceptVendorCommissionTerms({ organization, acceptVendorCommission: { versionId: id } }), 'Current 2% Vendor commission Terms accepted.')} />}
        {!admin && (owner || account?.permissions.includes('staff.manage')) && section === 'Team accounts' && <TeamAccounts owner={owner} busy={busy} members={team} invitations={invitations} onInvite={data => void act(async () => { await client.inviteVendorTeam({ organization, idempotencyKey: invitationKey, inviteVendorTeam: data }); setInvitationKey(crypto.randomUUID()) }, 'Staff invitation queued.')} onChange={(member, change) => void act(() => client.changeVendorTeamMember({ organization, membership: member.id, changeVendorTeamMember: { lockVersion: member.lockVersion, ...change } }), 'Staff access updated; the Vendor Owner was notified.')} onRevoke={invitation => void act(() => client.revokeVendorTeamInvitation({ organization, invitation: invitation.id, vendorVersionMutation: { lockVersion: invitation.lockVersion } }), 'Staff invitation revoked; the Vendor Owner was notified.')} />}
        {!admin && owner && section === 'Activation' && <Activation readiness={readiness} busy={busy} dashboardPath={dashboardPath} onActivate={() => void act(() => client.activateVendorMarketplace({ organization, vendorVersionMutation: { lockVersion } }), 'Store Activation evaluated; Marketplace Discoverability remains separate.')} />}
      </section></div>
  </main>
}

function Overview({ readiness }: { readiness: VendorReadiness | null }) { if (!readiness) return null; return <><div><p className="text-sm font-semibold text-action-primary">Canonical sequence</p><h2 className="text-2xl font-bold">Vendor Portal Account Active → Vendor Onboarding</h2><p>Store Verification and Store Setup are separate workstreams. Setup may continue during manual Admin review.</p></div><div className="grid gap-4 sm:grid-cols-2"><StateCard title="Store Verification" state={readiness.storeVerificationStatus} text="Legal, identity, registration, tax and regulatory evidence; Admin approval required." /><StateCard title="Store Setup" state={readiness.storeSetupStatus} text="Public profile, bulk, fulfillment, Xendit, commission, payment and refunds." /><StateCard title="Store Activation" state={readiness.activationStatus} text="All mandatory onboarding gates passed." /><StateCard title="Marketplace Discoverability" state={readiness.discoverabilityStatus} text="Separate listing, inventory and product-compliance gate." /></div><ReadinessPanel readiness={readiness} /></> }
function StateCard({ title, state, text }: { title: string; state: string; text: string }) { return <article className="rounded-card border border-border-default bg-surface-primary p-5"><div className="flex justify-between gap-3"><h3 className="font-bold">{title}</h3><Pill value={state} /></div><p className="mt-3 text-sm">{text}</p></article> }
function ReadinessPanel({ readiness }: { readiness: VendorReadiness | null }) { if (!readiness) return null; return <div className="space-y-4"><h2 className="text-xl font-bold">Requirements and statuses</h2><p className="text-sm">Requirement Level is applicability; Status is progress/review. NOT_APPLICABLE is only for a conditionally required item that does not apply.</p><ul className="divide-y divide-border-default rounded-card border border-border-default bg-surface-primary px-5">{readiness.checklist.map(item => <li key={item.id} className="py-4"><div className="flex flex-wrap justify-between gap-3"><div><p className="text-xs font-semibold text-action-primary">{label(item.section)}</p><strong>{item.label}</strong></div><div className="flex gap-2"><Pill value={item.requirementLevel} /><Pill value={item.status} /></div></div>{item.reason && <p className="mt-2 text-sm">{item.reason}</p>}<p className="mt-1 text-xs">Next: {label(item.nextAction)}</p></li>)}</ul></div> }

function BusinessIdentity({ business, setBusiness, emailVerifiedAt, busy, onSave, onRequest, onConfirm }: { business: VendorBusinessDraft; setBusiness: (v: VendorBusinessDraft) => void; emailVerifiedAt: string | null; busy: boolean; onSave: () => void; onRequest: () => void; onConfirm: (code: string) => void }) {
  const sole = business.businessType === 'SOLE_PROPRIETORSHIP'; const [code, setCode] = useState('')
  return <form className="space-y-6" onSubmit={e => { e.preventDefault(); onSave() }}><Heading stream="Store Verification" title="Business Type and legal identity" text="Business Type controls registered-name fields, authority, identity evidence and applicable documents." /><div className="grid gap-4 sm:grid-cols-2"><Select title="Business Type" value={business.businessType ?? ''} onChange={e => setBusiness({ ...business, businessType: e.target.value as VendorBusinessDraftBusinessTypeEnum })} required><option value="">Select</option>{businessTypes.map(v => <option key={v} value={v}>{label(v)}</option>)}</Select><Field label="Business or Store Name" value={business.storeName ?? ''} onChange={e => setBusiness({ ...business, storeName: e.target.value })} required /><Field label="Legal identity / registered name" value={business.legalName ?? ''} onChange={e => setBusiness({ ...business, legalName: e.target.value })} required /><Field label="Date of Establishment" type="date" value={business.establishedOn ?? ''} onChange={e => setBusiness({ ...business, establishedOn: e.target.value })} required />{sole ? <><Field label="Registered surname" value={business.individualRegisteredName?.surname ?? ''} onChange={e => setBusiness({ ...business, individualRegisteredName: { surname: e.target.value, firstName: business.individualRegisteredName?.firstName ?? '' } })} required /><Field label="Registered first name" value={business.individualRegisteredName?.firstName ?? ''} onChange={e => setBusiness({ ...business, individualRegisteredName: { surname: business.individualRegisteredName?.surname ?? '', firstName: e.target.value } })} required /><Field label="Government ID type" value={business.governmentIdType ?? ''} onChange={e => setBusiness({ ...business, governmentIdType: e.target.value })} required /><Field label="Government ID number" value={business.governmentIdNumber ?? ''} onChange={e => setBusiness({ ...business, governmentIdNumber: e.target.value })} /></> : <Field label="Company registered name" value={business.companyRegisteredName ?? ''} onChange={e => setBusiness({ ...business, companyRegisteredName: e.target.value })} required />}<Field label="Store Email" type="email" value={business.storeEmail ?? ''} onChange={e => setBusiness({ ...business, storeEmail: e.target.value })} required /><Field label="Store Phone" value={business.storePhone ?? ''} onChange={e => setBusiness({ ...business, storePhone: e.target.value })} required /></div><div className="rounded-card border border-border-default p-5"><p>{emailVerifiedAt ? `Store Email verified ${stamp(emailVerifiedAt)}` : 'Store Email verification is required before submission.'}</p><div className="mt-3 flex flex-wrap gap-3"><Button type="button" variant="secondary" disabled={busy || !business.storeEmail} onClick={onRequest}>Send verification code</Button>{!emailVerifiedAt && <><input className={inputClass} aria-label="Six-digit verification code" inputMode="numeric" maxLength={6} value={code} onChange={e => setCode(e.target.value.replace(/\D/g, ''))} /><Button type="button" disabled={busy || code.length !== 6} onClick={() => onConfirm(code)}>Confirm code</Button></>}</div></div><Actions busy={busy} /></form>
}

function ContactsLocation({ business, setBusiness, busy, onSave }: { business: VendorBusinessDraft; setBusiness: (v: VendorBusinessDraft) => void; busy: boolean; onSave: () => void }) {
  const contacts = business.contacts?.length ? business.contacts : [emptyContact()]
  const update = (i: number, patch: Partial<VendorBusinessContact>) => setBusiness({ ...business, contacts: contacts.map((c, p) => p === i ? { ...c, ...patch } : c) })
  return <form className="space-y-6" onSubmit={e => { e.preventDefault(); onSave() }}><Heading stream="Store Verification" title="Contacts, supplier profile and registered location" /><div className="grid gap-4 sm:grid-cols-2"><Select title="Supplier Type" value={business.classification ?? ''} onChange={e => setBusiness({ ...business, classification: e.target.value as VendorBusinessDraftClassificationEnum })} required><option value="">Select</option><option value="WHOLESALER_DISTRIBUTOR">Wholesaler / Distributor</option><option value="RETAIL_HARDWARE_STORE">Retail Hardware Store</option><option value="SPECIALIZED_SUPPLIER">Specialized Supplier</option></Select><div><p className="text-sm font-semibold">Supplier Niches</p><div className="mt-2 max-h-64 overflow-y-auto border border-border-default p-3">{niches.map(v => <Check key={v} title={label(v)} checked={business.niches?.includes(v as VendorBusinessDraftNichesEnum) ?? false} onChange={e => setBusiness({ ...business, niches: e.target.checked ? [...(business.niches ?? []), v as VendorBusinessDraftNichesEnum] : (business.niches ?? []).filter(n => n !== v) })} />)}</div></div>{business.niches?.includes('OTHER') && <Field label="Other niche (rentals unsupported)" value={business.otherNiche ?? ''} onChange={e => setBusiness({ ...business, otherNiche: e.target.value })} required />}</div><fieldset className="grid gap-4 sm:grid-cols-2"><legend className="font-bold">Registered address and Google Maps pin</legend>{(['street', 'barangay', 'city', 'province', 'postalCode'] as const).map(k => <Field key={k} label={label(k)} value={business.address?.[k] ?? ''} onChange={e => setBusiness({ ...business, address: { street: '', barangay: '', city: '', province: '', postalCode: '', ...business.address, [k]: e.target.value } })} required />)}<Field label="Latitude" type="number" step="any" value={business.address?.latitude ?? ''} onChange={e => setBusiness({ ...business, address: { street: '', barangay: '', city: '', province: '', postalCode: '', ...business.address, latitude: Number(e.target.value) } })} required /><Field label="Longitude" type="number" step="any" value={business.address?.longitude ?? ''} onChange={e => setBusiness({ ...business, address: { street: '', barangay: '', city: '', province: '', postalCode: '', ...business.address, longitude: Number(e.target.value) } })} required /></fieldset><div className="space-y-4"><div className="flex justify-between gap-3"><h3 className="font-bold">Primary and additional business contacts</h3><Button type="button" variant="secondary" onClick={() => setBusiness({ ...business, contacts: [...contacts, { ...emptyContact(), isPrimary: false }] })}>Add contact</Button></div>{contacts.map((c, i) => <fieldset key={i} className="grid gap-4 rounded-card border border-border-default p-5 sm:grid-cols-2"><legend>Contact {i + 1}</legend><Field label="Full name" value={c.fullName} onChange={e => update(i, { fullName: e.target.value })} required /><Field label="Position" value={c.position} onChange={e => update(i, { position: e.target.value })} required /><Field label="Email" type="email" value={c.email} onChange={e => update(i, { email: e.target.value })} required /><Field label="Telephone" value={c.telephoneE164} onChange={e => update(i, { telephoneE164: e.target.value })} required /><Check title="Primary Business Contact" checked={c.isPrimary} onChange={e => setBusiness({ ...business, contacts: contacts.map((x, p) => ({ ...x, isPrimary: p === i ? e.target.checked : false })) })} /><Check title="Authorized representative" checked={c.authorizedRepresentative} onChange={e => update(i, { authorizedRepresentative: e.target.checked })} /><Check title="Verification communications" checked={c.verificationCommunication} onChange={e => update(i, { verificationCommunication: e.target.checked })} /><Check title="Account administration communications" checked={c.accountAdministrationCommunication} onChange={e => update(i, { accountAdministrationCommunication: e.target.checked })} /><Check title="General administration communications" checked={c.generalAdministrationCommunication} onChange={e => update(i, { generalAdministrationCommunication: e.target.checked })} /></fieldset>)}</div><Actions busy={busy} /></form>
}

function Evidence({ documents, busy, onUpload }: { documents: VendorDocument[]; busy: boolean; onUpload: (type: typeof documentTypes[number], file: File) => void }) { return <div className="space-y-6"><Heading stream="Store Verification" title="Business, permit, tax and regulatory evidence" text="Uploading never means automatic verification. Applicable mandatory evidence requires file-safety checks and manual Admin approval." /><form className="grid gap-4 rounded-card border border-border-default p-5 sm:grid-cols-2" onSubmit={e => { e.preventDefault(); const d = new FormData(e.currentTarget); const file = d.get('file'); if (file instanceof File) onUpload(String(d.get('type')) as typeof documentTypes[number], file) }}><Select title="Document Type" name="type">{documentTypes.map(v => <option key={v}>{v}</option>)}</Select><Field label="Private evidence file" name="file" type="file" accept=".pdf,.png,.jpg,.jpeg" required /><Button type="submit" disabled={busy}>Upload evidence</Button></form><ul className="divide-y divide-border-default">{documents.map(d => <li key={d.id} className="flex justify-between gap-3 py-4"><div><strong>{label(d.documentType)}</strong><p>Version {d.version} · file safety: {label(d.scanState)}</p>{d.reviewReason && <p>{d.reviewReason}</p>}</div><Pill value={d.status} /></li>)}</ul><FinishLater /></div> }

function TaxProfile({ tax, documents, owner, busy, onSave }: { tax: VendorTaxProfile | null; documents: VendorDocument[]; owner: boolean; busy: boolean; onSave: (profile: Record<string, unknown>, attest: boolean) => void }) {
  const source = tax?.data ?? {}; const [attest, setAttest] = useState(false); const fields = [['taxpayer_key', 'Taxpayer key'], ['legal_name', 'Legal name'], ['trade_name', 'Trade name'], ['tin', 'TIN'], ['registration_category', 'BIR registration category'], ['invoice_method', 'Invoice method'], ['invoice_coverage', 'Invoice coverage']] as const
  return <form className="space-y-5" onSubmit={e => { e.preventDefault(); const d = new FormData(e.currentTarget); const result: Record<string, unknown> = {}; d.forEach((v, k) => { if (typeof v === 'string' && v) result[k] = k === 'fiscal_year_start_month' ? Number(v) : v }); onSave(result, attest) }}><Heading stream="Store Verification" title="Vendor Tax Profile" text="The versioned Vendor Tax Profile is the single legal-tax source. Payment Configuration references it and does not recollect tax data." /><div className="grid gap-4 sm:grid-cols-2">{fields.map(([k, t]) => <Field key={k} name={k} label={t} defaultValue={String(source[k] ?? '')} required />)}<Field name="branch_code" label="Branch code" defaultValue={String(source.branch_code ?? '')} /><Field name="fiscal_year_start_month" label="Fiscal year start month" type="number" min="1" max="12" defaultValue={String(source.fiscal_year_start_month ?? 1)} required /><Field name="effective_from" label="Effective from" type="date" defaultValue={String(source.effective_from ?? '')} required /><Select title="Entity classification" name="entity_class" defaultValue={String(source.entity_class ?? 'INDIVIDUAL')}><option>INDIVIDUAL</option><option>CORPORATE</option></Select><Select title="VAT or Non-VAT classification" name="vat_category" defaultValue={String(source.vat_category ?? '')} required><option value="">Select</option><option value="VAT_REGISTERED">VAT Registered</option><option value="NON_VAT">Non-VAT</option></Select><Select title="BIR Certificate of Registration evidence" name="bir_cor_version_id" defaultValue={String(source.bir_cor_version_id ?? '')} required><option value="">Select version</option>{documents.filter(d => d.documentType === 'BIR_COR').map(d => <option key={d.id} value={d.id}>BIR COR version {d.version}</option>)}</Select><Field name="declaration_receipt" label="Sworn declaration / withholding evidence reference" defaultValue={String(source.declaration_receipt ?? '')} /></div>{owner && <Check title="I am the Owner and attest this Tax Profile version" checked={attest} onChange={e => setAttest(e.target.checked)} />}<StatusMessage tone="info">TEST/DEMO only: no live payment processing or BIR remittance. A Sworn Declaration does not automatically determine tax treatment, and Xendit does not prove withholding responsibility.</StatusMessage><Button type="submit" disabled={busy}>{attest ? 'Attest and submit version' : 'Save correction draft'}</Button></form>
}

function VerificationReview({ readiness, business, documents, tax, reason, busy, dashboardPath, onSubmit, onProceed }: { readiness: VendorReadiness | null; business: VendorBusinessDraft; documents: VendorDocument[]; tax: VendorTaxProfile | null; reason: string | null; busy: boolean; dashboardPath: string; onSubmit: () => void; onProceed: () => void }) { const pending = readiness?.storeVerificationStatus === 'PENDING_VERIFICATION'; return <div className="space-y-6"><Heading stream="Store Verification" title="Review and submit" text="Confirm identity, contacts, address/map pin, registration, permits, BIR/TIN, tax evidence and Privacy Notice acknowledgment." />{reason && <StatusMessage tone="error">{reason}</StatusMessage>}<ReviewDetails value={business} /><p>{documents.length} evidence version(s) · Tax Profile: {label(tax?.status ?? 'NOT_STARTED')}</p>{pending ? <StatusMessage tone="success">Store Verification is PENDING_VERIFICATION. Store Setup may continue during Admin review.</StatusMessage> : <Button disabled={busy} onClick={onSubmit}>Submit Store Verification</Button>}<div className="flex gap-3"><Button disabled={busy} onClick={onProceed}>Proceed to Store Setup</Button><FinishLater href={dashboardPath} /></div></div> }

function StoreProfile({ setup, media, storeName, busy, onUpload, onPreview, onRemove }: { setup: VendorSetup | null; media: VendorStoreMedia[]; storeName: string; busy: boolean; onUpload: (kind: 'LOGO' | 'BANNER' | 'PROMOTIONAL', alt: string, file: File) => void; onPreview: (id: string) => void; onRemove: (id: string) => void }) { return <div className="space-y-6"><Heading stream="Store Setup" title="Public Store Profile" text={`Pre-populated Store Name: ${storeName || 'Not recorded'}. Add description, logo/profile image, banner and optional promotional media.`} /><p>Current description: {setup?.store?.description ?? 'Not saved'}</p><form className="grid gap-4 rounded-card border border-border-default p-5 sm:grid-cols-2" onSubmit={e => { e.preventDefault(); const d = new FormData(e.currentTarget); const file = d.get('file'); if (file instanceof File) onUpload(String(d.get('kind')) as 'LOGO' | 'BANNER' | 'PROMOTIONAL', String(d.get('alt')), file) }}><Select title="Media purpose" name="kind"><option>LOGO</option><option>BANNER</option><option>PROMOTIONAL</option></Select><Field label="Accessible media description" name="alt" required /><Field label="Media file" name="file" type="file" accept=".png,.jpg,.jpeg" required /><Button type="submit" disabled={busy}>Upload Store media</Button></form>{media.map(m => <div key={m.id} className="flex flex-wrap items-center justify-between gap-3 border-t border-border-default py-3"><span>{label(m.kind)} · {m.altText}</span><div className="flex flex-wrap items-center gap-2"><Pill value={m.reviewStatus} /><Button type="button" variant="secondary" disabled={busy || m.scanState !== 'CLEAN'} onClick={() => onPreview(m.id)}>Preview</Button><Button type="button" variant="secondary" disabled={busy} onClick={() => onRemove(m.id)}>Remove</Button></div></div>)}</div> }

function Fulfillment({ setup, busy, onSave }: { setup: VendorSetup | null; busy: boolean; onSave: (data: Omit<SaveVendorStore, 'lockVersion'>) => void }) {
  const [fulfillment, setFulfillment] = useState<SaveVendorStore['fulfillment']>(setup?.store?.deliveryEnabled ? setup.store.pickupEnabled ? 'BOTH' : 'VENDOR_DELIVERY' : 'SELF_PICKUP'); const [vehicles, setVehicles] = useState<VendorVehicle[]>(setup?.deliveryVehicles.length ? setup.deliveryVehicles : [emptyVehicle()]); const delivery = fulfillment !== 'SELF_PICKUP'
  const update = (i: number, patch: object) => setVehicles(vehicles.map((v, p) => p === i ? { ...v, ...patch } as VendorVehicle : v))
  return <form className="space-y-6" onSubmit={e => { e.preventDefault(); const d = new FormData(e.currentTarget); onSave({ description: String(d.get('description')), publicEmail: String(d.get('email') || ''), publicPhone: String(d.get('phone') || ''), bulkOrderCapable: d.get('bulk') === 'YES', fulfillment, codEnabled: Boolean(d.get('cod')), inStorePaymentEnabled: Boolean(d.get('in_store')), onlinePaymentEnabled: true, refundConfiguration: { onlineRefundSupported: true, physicalReimbursementSupported: Boolean(d.get('physical_refund')) }, deliveryVehicles: delivery ? vehicles : [], hours: Array.from({ length: 7 }, (_, weekday) => ({ weekday, closed: Boolean(d.get(`closed${weekday}`)), opensAt: String(d.get(`opens${weekday}`) || ''), closesAt: String(d.get(`closes${weekday}`) || '') })) }) }}><Heading stream="Store Setup" title="Bulk capability, fulfillment and refunds" /><div className="grid gap-4 sm:grid-cols-2"><Field label="Public Store description" name="description" defaultValue={setup?.store?.description ?? ''} required /><Field label="Public email" name="email" type="email" defaultValue={setup?.store?.publicEmail ?? ''} /><Field label="Public phone" name="phone" defaultValue={setup?.store?.publicPhone ?? ''} /><Select title="Bulk Order Capability" name="bulk" defaultValue={setup?.bulkOrderCapable ? 'YES' : 'NO'}><option value="YES">Yes — Item-Based and Project-Based Procurement</option><option value="NO">No — Item-Based Procurement only</option></Select><Select title="Fulfillment Configuration" value={fulfillment} onChange={e => setFulfillment(e.target.value as SaveVendorStore['fulfillment'])}><option value="SELF_PICKUP">Self-Pickup</option><option value="VENDOR_DELIVERY">Vendor Delivery</option><option value="BOTH">Both</option></Select><Check title="Cash on Delivery" name="cod" disabled={!delivery} defaultChecked={setup?.store?.codEnabled} /><Check title="In-Store Payment" name="in_store" disabled={fulfillment === 'VENDOR_DELIVERY'} defaultChecked={setup?.store?.inStorePaymentEnabled} /><Check title="Physical reimbursement capability" name="physical_refund" defaultChecked /></div>{delivery && <div className="space-y-4"><div className="flex justify-between"><h3 className="font-bold">Conditional delivery vehicles and rates</h3><Button type="button" variant="secondary" onClick={() => setVehicles([...vehicles, emptyVehicle()])}>Add vehicle</Button></div>{vehicles.map((v, i) => <fieldset key={i} className="grid gap-4 rounded-card border border-border-default p-5 sm:grid-cols-3"><legend>Vehicle {i + 1}</legend><Select title="Vehicle type" value={v.vehicleType} onChange={e => update(i, { vehicleType: e.target.value as VendorVehicle['vehicleType'] })}><option>MOTORCYCLE</option><option>PICKUP</option><option>VAN</option><option>TRUCK</option><option>CUSTOM</option></Select>{v.vehicleType === 'TRUCK' && <Select title="Subtype" value={v.vehicleSubtype ?? ''} onChange={e => update(i, { vehicleSubtype: e.target.value as VendorVehicle['vehicleSubtype'] })}><option value="">Select</option><option>OPEN_TRUCK</option><option>FLATBED_TRUCK</option><option>WING_VAN</option></Select>}{v.vehicleType === 'CUSTOM' && <Field label="Custom type" value={v.customVehicleType ?? ''} onChange={e => update(i, { customVehicleType: e.target.value })} required />}<Field label="Vehicle name" value={v.name} onChange={e => update(i, { name: e.target.value })} required />{(['numberAvailable', 'capacityKg', 'cargoLengthM', 'cargoWidthM', 'cargoHeightM', 'baseFeeCentavos', 'perKmCentavos', 'maximumDistanceKm'] as const).map(k => <Field key={k} label={label(k)} type="number" min="0" value={v[k]} onChange={e => update(i, { [k]: Number(e.target.value) })} required />)}<Field label="Heavy vehicle classification" value={v.heavyVehicleClassification} onChange={e => update(i, { heavyVehicleClassification: e.target.value })} required /></fieldset>)}</div>}<fieldset><legend className="font-bold">Operating hours (Asia/Manila)</legend>{['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'].map((day, i) => { const h = setup?.hours.find(x => x.weekday === i); return <div key={day} className="grid gap-3 border-t border-border-default py-3 sm:grid-cols-3"><Check title={`${day} closed`} name={`closed${i}`} defaultChecked={h?.closed ?? false} /><Field label="Opens" name={`opens${i}`} type="time" defaultValue={h?.opensAt?.slice(0, 5) ?? '08:00'} /><Field label="Closes" name={`closes${i}`} type="time" defaultValue={h?.closesAt?.slice(0, 5) ?? '17:00'} /></div> })}</fieldset><Actions busy={busy} labelText="Save Store Setup" /></form>
}

function PaymentCommission({ setup, tax, terms, busy, onConnect, onReconcile, onAccept }: { setup: VendorSetup | null; tax: VendorTaxProfile | null; terms: VendorCommissionTerms | null; busy: boolean; onConnect: () => void; onReconcile: () => void; onAccept: (id: string) => void }) { const status = setup?.payment?.status ?? 'NOT_STARTED'; const agreement = terms?.agreement as Record<string, unknown> | null | undefined; return <div className="space-y-6"><Heading stream="Store Setup" title="Xendit, tax reference, commission, payments and refunds" /><StatusMessage tone="info">Xendit xenPlatform onboarding is mandatory for every Vendor seeking Store Activation. Capstone TEST/DEMO does not authorize live payments, prove withholding responsibility or remit taxes.</StatusMessage><StateCard title="Vendor Tax Profile reference" state={tax?.status ?? 'NOT_STARTED'} text="The single legal-tax source; Payment Configuration does not duplicate it." /><div className="rounded-card border border-border-default p-5"><h3 className="font-bold">Xendit xenPlatform</h3><Pill value={status} /><div className="mt-3 flex gap-3"><Button disabled={busy || ['TEST_CONNECTING', 'TEST_RECONCILE_REQUIRED'].includes(status)} onClick={onConnect}>Connect Xendit TEST account</Button>{['TEST_CONNECTING', 'TEST_RECONCILE_REQUIRED'].includes(status) && <Button variant="secondary" onClick={onReconcile}>Reconcile attempt</Button>}</div></div><div className="rounded-card border border-border-default p-5"><h3 className="font-bold">Payment methods and refund configuration</h3><p>Online payment references Xendit. Physical methods follow fulfillment. Cancellation Refund and Dispute-Conclusion Refund remain separate triggers and records.</p></div><div className="rounded-card border border-border-default p-5"><h3 className="font-bold">2% Vendor-paid commission</h3><p>FIN-03 monthly billing: completed materials value after discounts, excluding included materials VAT. No internal wallet or platform escrow.</p>{terms?.contentAvailable && typeof agreement?.content === 'string' ? <><div className="my-3 max-h-72 overflow-y-auto whitespace-pre-wrap border-y border-border-default py-3">{agreement.content}</div><Button disabled={busy || Boolean(agreement.accepted_at)} onClick={() => typeof agreement.id === 'string' && onAccept(agreement.id)}>{agreement.accepted_at ? 'Terms accepted' : 'Accept Commission Terms'}</Button></> : <StatusMessage tone="error">Approved Commission Terms are unavailable; activation remains blocked.</StatusMessage>}</div><FinishLater /></div> }

function TeamAccounts({ owner, busy, members, invitations, onInvite, onChange, onRevoke }: { owner: boolean; busy: boolean; members: VendorTeamMember[]; invitations: VendorTeamInvitation[]; onInvite: (data: { fullName: string; email: string; telephoneE164?: string; role: InviteVendorTeamRoleEnum; canManageStaff: boolean; expiresAt: Date }) => void; onChange: (member: VendorTeamMember, change: Omit<ChangeVendorTeamMember, 'lockVersion'>) => void; onRevoke: (invitation: VendorTeamInvitation) => void }) {
  const roles = [...(owner ? ['STORE_MANAGER'] : []), 'STORE_STAFF', 'CUSTOMER_SERVICE', 'INVENTORY', 'FULFILLMENT'] as InviteVendorTeamRoleEnum[]
  return <div className="space-y-6"><Heading stream="Optional Store Setup" title="Vendor Team Accounts" text="Optional; never blocks activation. Staff use individual accounts, do not share Owner credentials, repeat onboarding or bypass Store Activation." /><form className="grid gap-4 rounded-card border border-border-default p-5 sm:grid-cols-2" onSubmit={e => { e.preventDefault(); const d = new FormData(e.currentTarget); const role = String(d.get('role')) as InviteVendorTeamRoleEnum; onInvite({ fullName: String(d.get('name')), email: String(d.get('email')), telephoneE164: String(d.get('phone') || ''), role, canManageStaff: owner && role === 'STORE_MANAGER' && Boolean(d.get('delegation')), expiresAt: new Date(String(d.get('expires'))) }) }}><Field label="Staff name" name="name" required /><Field label="Individual email" name="email" type="email" required /><Field label="Telephone" name="phone" /><Select title="Fixed role" name="role">{roles.map(r => <option key={r}>{r}</option>)}</Select>{owner && <Check title="Allow this Store Manager to manage staff accounts" name="delegation" />}<Field label="Invitation expiry" name="expires" type="datetime-local" required /><Button type="submit" disabled={busy}>Send invitation</Button></form><div className="space-y-4"><h3 className="font-bold">Team members</h3>{members.map(m => { const manageable = m.role !== 'OWNER' && (owner || m.role !== 'STORE_MANAGER'); return <article key={m.id} className="rounded-card border border-border-default p-5"><p><strong>{m.name}</strong> · {label(m.role)} · {label(m.status)}{m.canManageStaff ? ' · delegated staff management' : ''}</p>{manageable && <div className="mt-4 grid gap-3 lg:grid-cols-3"><form className="flex items-end gap-2" onSubmit={e => { e.preventDefault(); const d = new FormData(e.currentTarget); onChange(m, { role: String(d.get('role')) as ChangeVendorTeamMemberRoleEnum }) }}><Select title={`Role for ${m.name}`} name="role" defaultValue={m.role}>{roles.map(r => <option key={r}>{r}</option>)}</Select><Button type="submit" variant="secondary" disabled={busy}>Change role</Button></form><form className="flex items-end gap-2" onSubmit={e => { e.preventDefault(); const d = new FormData(e.currentTarget); onChange(m, { status: String(d.get('status')) as ChangeVendorTeamMemberStatusEnum }) }}><Select title={`Access status for ${m.name}`} name="status" defaultValue={m.status}><option>ACTIVE</option><option>SUSPENDED</option><option>DEACTIVATED</option></Select><Button type="submit" variant="secondary" disabled={busy}>Update access</Button></form>{owner && m.role === 'STORE_MANAGER' && <form className="flex items-end gap-2" onSubmit={e => { e.preventDefault(); const d = new FormData(e.currentTarget); onChange(m, { canManageStaff: Boolean(d.get('delegation')) }) }}><Check title="Allow this Store Manager to manage staff accounts" name="delegation" defaultChecked={m.canManageStaff} /><Button type="submit" variant="secondary" disabled={busy}>Update delegation</Button></form>}</div>}</article> })}</div><div className="space-y-3"><h3 className="font-bold">Invitations</h3>{invitations.map(i => { const revocable = !i.acceptedAt && !i.revokedAt && (owner || i.role !== 'STORE_MANAGER'); return <div key={i.id} className="flex flex-wrap items-center justify-between gap-3 border-t border-border-default py-3"><p>{i.fullName ?? i.normalizedEmail} · {label(i.role)} · expires {stamp(i.expiresAt)}{i.revokedAt ? ` · revoked ${stamp(i.revokedAt)}` : ''}</p>{revocable && <Button type="button" variant="secondary" disabled={busy} onClick={() => onRevoke(i)}>Revoke invitation</Button>}</div> })}</div></div>
}
function Activation({ readiness, busy, dashboardPath, onActivate }: { readiness: VendorReadiness | null; busy: boolean; dashboardPath: string; onActivate: () => void }) { return <div className="space-y-6"><Heading stream="Store Setup" title="Store Activation" text="Product listing is not an activation prerequisite. Marketplace Discoverability remains a separate eligibility state." /><ReadinessPanel readiness={readiness} /><Button disabled={busy || !readiness?.ready} onClick={onActivate}>Activate Store</Button>{readiness?.activationStatus === 'ACTIVE' && readiness.discoverabilityStatus !== 'DISCOVERABLE' && <StatusMessage tone="info">Store Active; not discoverable until an eligible active listing, inventory and applicable product compliance exist. PS Mark/ICC Sticker evidence still gates regulated listings.</StatusMessage>}<FinishLater href={dashboardPath} /></div> }

function Queue({ rows, busy, page, lastPage, setPage, onOpen }: { rows: VendorVerificationRow[]; busy: boolean; page: number; lastPage: number; setPage: (v: number) => void; onOpen: (id: string) => void }) { return <div className="space-y-5"><h2 className="text-2xl font-bold">Vendor onboarding queue</h2><div className="overflow-x-auto"><table className="w-full text-left"><thead><tr><th className="p-3">Store</th><th className="p-3">Verification</th><th className="p-3">Setup</th><th className="p-3">Activation</th><th className="p-3">Discoverability</th><th className="p-3">Action</th></tr></thead><tbody>{rows.map(r => <tr key={r.id} className="border-t border-border-default"><td className="p-3 font-semibold">{r.storeName}</td><td className="p-3">{label(r.storeVerificationStatus)}</td><td className="p-3">{label(r.storeSetupStatus)}</td><td className="p-3">{label(r.activationStatus)}</td><td className="p-3">{label(r.discoverabilityStatus)}</td><td className="p-3"><Button disabled={busy} onClick={() => onOpen(r.id)}>Review</Button></td></tr>)}</tbody></table></div><div className="flex gap-3"><Button variant="secondary" disabled={page <= 1} onClick={() => setPage(page - 1)}>Previous</Button><span>Page {page} of {lastPage}</span><Button variant="secondary" disabled={page >= lastPage} onClick={() => setPage(page + 1)}>Next</Button></div></div> }

type DocumentDecision = { lockVersion: number; decision: VendorReviewDecisionEnum; reason?: string; verifiedReference?: string; verifiedIssuedOn?: string; verifiedExpiresOn?: string; verifiedExpiryNotApplicable: boolean; sourceReference: string; remarks?: string; immediateRestriction: boolean }
function AdminVerification({ readiness, business, documents, tax, busy, lockVersion, onBusiness, onDocument, onTax }: { readiness: VendorReadiness | null; business: VendorBusinessDraft; documents: VendorDocument[]; tax: VendorTaxProfile | null; busy: boolean; lockVersion: number; onBusiness: (d: VendorReviewDecisionEnum, r: string, regulatory: boolean, basis: string) => void; onDocument: (doc: VendorDocument, d: DocumentDecision) => void; onTax: (v: string, d: VendorReviewDecisionEnum, r: string) => void }) { return <div className="space-y-6"><Heading stream="Admin" title="Store Verification manual review" text="Validate completeness, files, dependencies, malware state and applicable DTI/SEC/CDA/LGU/BIR/TIN evidence. Every decision is audit logged." /><ReadinessPanel readiness={readiness} /><ReviewDetails value={business} /><DecisionForm title="Business and dependency review" busy={busy} extended onReview={(d, r, form) => onBusiness(d, r, form.get('regulatory') === 'YES', String(form.get('basis') || ''))} />{documents.map(doc => <div key={doc.id} className="rounded-card border border-border-default p-5"><div className="flex justify-between"><strong>{label(doc.documentType)} version {doc.version}</strong><Pill value={doc.status} /></div><DocumentDecisionForm busy={busy} lockVersion={lockVersion} onReview={d => onDocument(doc, d)} /></div>)}{tax?.versionId && <DecisionForm title="Independent Vendor Tax Profile review" busy={busy} onReview={(d, r) => onTax(tax.versionId!, d, r)} />}</div> }
function AdminSetup({ readiness, media, busy, onReview }: { readiness: VendorReadiness | null; media: VendorStoreMedia[]; busy: boolean; onReview: (id: string, d: VendorReviewDecisionEnum, r: string) => void }) { return <div className="space-y-6"><Heading stream="Admin" title="Store Setup review" text="Store Setup completion never implies Store Verification approval. Non-reviewed setup items use COMPLETED." /><ReadinessPanel readiness={readiness} />{media.map(m => <div key={m.id} className="rounded-card border border-border-default p-5"><strong>{label(m.kind)} · {m.altText}</strong><DecisionForm title="Media decision" busy={busy} onReview={(d, r) => onReview(m.id, d, r)} /></div>)}</div> }
function DecisionForm({ title, busy, extended = false, onReview }: { title: string; busy: boolean; extended?: boolean; onReview: (d: VendorReviewDecisionEnum, r: string, form: FormData) => void }) { return <form className="mt-4 grid gap-3" onSubmit={e => { e.preventDefault(); const f = new FormData(e.currentTarget); onReview(String(f.get('decision')) as VendorReviewDecisionEnum, String(f.get('reason') || ''), f) }}><h3 className="font-bold">{title}</h3><Select title="Decision" name="decision"><option value="RETURN_FOR_CORRECTION">Return for Correction</option><option value="APPROVE">Approve</option><option value="REJECT">Reject</option></Select><Field label="Decision reason" name="reason" />{extended && <><Select title="Other regulatory evidence" name="regulatory"><option value="NO">Not Applicable</option><option value="YES">Conditionally Required</option></Select><Field label="Applicability/dependency basis" name="basis" required /></>}<Button type="submit" disabled={busy}>Record audit-logged decision</Button></form> }
function DocumentDecisionForm({ busy, lockVersion, onReview }: { busy: boolean; lockVersion: number; onReview: (d: DocumentDecision) => void }) { return <form className="mt-4 grid gap-3 sm:grid-cols-2" onSubmit={e => { e.preventDefault(); const f = new FormData(e.currentTarget); onReview({ lockVersion, decision: String(f.get('decision')) as VendorReviewDecisionEnum, reason: String(f.get('reason') || ''), verifiedReference: String(f.get('reference') || ''), verifiedIssuedOn: String(f.get('issued') || ''), verifiedExpiresOn: String(f.get('expires') || ''), verifiedExpiryNotApplicable: Boolean(f.get('no_expiry')), sourceReference: String(f.get('source')), remarks: String(f.get('remarks') || ''), immediateRestriction: Boolean(f.get('restrict')) }) }}><Select title="Decision" name="decision"><option value="RETURN_FOR_CORRECTION">Return for Correction</option><option value="APPROVE">Approve</option><option value="REJECT">Reject</option></Select><Field label="Document number" name="reference" /><Field label="Issue date" name="issued" type="date" /><Field label="Expiration date" name="expires" type="date" /><Check title="Expiration Date: Not Applicable" name="no_expiry" /><Field label="Document source (DTI/SEC/CDA/LGU/BIR/TIN)" name="source" required /><Field label="Decision reason" name="reason" /><Field label="Remarks" name="remarks" /><Check title="Critical issue needs immediate restriction" name="restrict" /><Button type="submit" disabled={busy}>Record document review</Button></form> }

function Heading({ stream, title, text }: { stream: string; title: string; text?: string }) { return <div><p className="text-sm font-semibold text-action-primary">{stream}</p><h2 className="text-2xl font-bold">{title}</h2>{text && <p className="mt-2">{text}</p>}</div> }
function Actions({ busy, labelText = 'Save & Continue' }: { busy: boolean; labelText?: string }) { return <div className="flex gap-3"><Button type="submit" disabled={busy}>{labelText}</Button><FinishLater /></div> }
function ReviewDetails({ value }: { value: object }) { return <dl className="space-y-3 rounded-card border border-border-default bg-surface-primary p-5">{Object.entries(value).map(([key, item]) => <div key={key}><dt className="text-xs font-semibold text-action-primary">{label(key)}</dt><dd className="break-words">{item === null || item === undefined || item === '' ? 'Not recorded' : Array.isArray(item) ? item.map((entry, index) => <div key={index}>{typeof entry === 'object' && entry !== null ? <ReviewDetails value={entry} /> : String(entry)}</div>) : typeof item === 'object' ? <ReviewDetails value={item} /> : typeof item === 'boolean' ? item ? 'Yes' : 'No' : String(item)}</dd></div>)}</dl> }
